//! `Idx`: a small enum numbered in the text order of its ids (generated by `cargo xtask gen-cards`)
//! or the per-game `Seat`. Index order is therefore the order the string engine's `BTreeMap`s
//! iterate in.

use crate::generated::*;
use crate::ids::Seat;

/// A closed id space with a dense integer index.
pub trait Idx: Copy + Ord {
    /// Number of values.
    const COUNT: usize;
    /// The dense index (text order).
    fn index(self) -> usize;
    /// The value with this index, if in range.
    fn from_index(index: usize) -> Option<Self>;
}

macro_rules! impl_idx {
    ($($t:ty),* $(,)?) => {$(
        impl Idx for $t {
            const COUNT: usize = <$t>::COUNT;
            #[inline]
            fn index(self) -> usize { <$t>::index(self) }
            #[inline]
            fn from_index(index: usize) -> Option<Self> { <$t>::from_index(index) }
        }
    )*};
}

impl_idx!(
    Ability, ActionCard, Agenda, Attachment, Breakthrough, Explore, GalacticEvent, GenericCard, Leader,
    PromissoryNote, PublicObjective, Relic, SecretObjective, StrategyCard, Technology, Faction, Planet,
    System, Token, Unit, Source, FactionTag, TechType, AgendaType, AgendaElects, LeaderType, LeaderWindow,
    ObjectivePhase, ExploreType, ExploreResolution, StrategyCardKind, PlanetTrait, Wormhole, TileBack,
    UnitBaseType,
);

/// Most owners one game can have (the players and every other owner that can appear on the board).
pub const MAX_OWNERS: usize = 16;

impl Idx for Seat {
    const COUNT: usize = MAX_OWNERS;
    #[inline]
    fn index(self) -> usize {
        usize::from(self.0)
    }
    #[inline]
    fn from_index(index: usize) -> Option<Self> {
        if index < MAX_OWNERS { Some(Seat(index as u8)) } else { None }
    }
}
